create function chat_verlauf_nach_loeschen() returns trigger language plpgsql as $$
begin
    execute format('update %I.chat_gespraech set verlauf_vollstaendig = false '
        || 'where verlauf_vollstaendig and id in (select gespraech_id from geloeschte_nachrichten)',
        tg_table_schema);
    return null;
end;
$$

create trigger chat_verlauf_nach_loeschen after delete on chat_nachricht
    referencing old table as geloeschte_nachrichten
    for each statement execute function chat_verlauf_nach_loeschen();
